command:
$HistoryLength=0;
PrependTo[$Path,"/u/home/r/rushil/.Mathematica/Applications"];
$FeynCalcStartupMessages=False;Get["FeynCalc`"];
gate[name_,test_]:=If[!TrueQ[test],Print["FAIL: ",name];Quit[1]];
SetAttributes[bounded,HoldFirst];bounded[v_,label_]:=MemoryConstrained[TimeConstrained[v,180,Print["FAIL: ",label," time"];Quit[1]],2*1024^3,Print["FAIL: ",label," memory"];Quit[1]];
mapped=bounded[Get[FileNameJoin[{Directory[],"Hqqprime","s08_result","s08_result.wl"}]],"accepted map read"];
gate["accepted complete coefficient map",TrueQ[mapped["MappingAccepted"]]&&TrueQ[mapped["ReductionCoverageComplete"]]&&And@@Values[mapped["Checks"]]];
component=mapped["Components"][[7]];
coefficients=Select[component["ReducedCoefficients"],#=!=0&]/.mapped["TransverseSubstitution"];
master=First[Keys[coefficients]];c=coefficients[master];
regions=Get[FileNameJoin[{Directory[],"common","s06_result","reference","s15_result.wl"}]]/.mapped["ScalarConventionRules"];
value=regions["OrdinaryMasters"][master];
Print["ACTUAL_COMPONENT=",InputForm[KeyTake[component,{"Sector","Kind","Index"}]]];
Print["ACTUAL_MASTER=",InputForm[master]];
Print["COEFFICIENT_BYTES=",ByteCount[c]];
num=Numerator[c];den=Denominator[c];
gate["numerator and denominator polynomial in D",PolynomialQ[num,D]&&PolynomialQ[den,D]];
Print["ACTUAL_COEFFICIENT_DENOMINATOR=",InputForm[den]];
Print["NUMERATOR_D_DEGREE=",Exponent[num,D]];
Print["DENOMINATOR_D_DEGREE=",Exponent[den,D]];
Print["DENOMINATOR_AT_D4=",InputForm[den/.D->4]];
nc=bounded[CoefficientList[num,D],"numerator D coefficients"];
dc=bounded[CoefficientList[den,D],"denominator D coefficients"];
gate["D coefficient reconstruction",bounded[Expand[num-Sum[nc[[j]]D^(j-1),{j,Length[nc]}]]===0&&Expand[den-Sum[dc[[j]]D^(j-1),{j,Length[dc]}]]===0,"D reconstruction"]];
Print["NUMERATOR_D_COEFFICIENT_BYTES=",ByteCount/@nc];
Print["DENOMINATOR_D_COEFFICIENTS=",InputForm[dc]];
Print["MASTER_SERIES_METADATA=",InputForm[Cases[value,q_SeriesData:>{q[[1]],q[[2]],q[[4]],q[[5]],q[[6]]},{0,Infinity}]]];
Print["ACTUAL_MASTER_VALUE=",InputForm[value]];
Print["PASS: s12_read_integration_input"];Quit[0];
